import pandas as pd
import numpy as np
import statsmodels.api as sm
from pathlib import Path
import matplotlib.pyplot as plt

DATA_FILE = Path(__file__).resolve().parent / "data" / "cs_total_payout_crsp.csv"
RESULTS_DIR = Path(__file__).resolve().parent / "results"
RESULTS_DIR.mkdir(exist_ok=True)
FIGURE_DIR = RESULTS_DIR


data = pd.read_csv(DATA_FILE)
data["main_sample"] = data["year"].between(1947, 2025)

##########
### B1 ###
##########

data["X"] = data["DIV"] + data["DL"] + data["BB"] - data["ISS"] - data["IPO"]
data["V_t"] = data["V"].shift(1)
data["R_1"] = (data["V_t"] + data["X"]) / data["V"]

print(
    "Cashflows negative in {} out of {} years.".format(
        (data.loc[data["main_sample"]]["X"] < 0).sum(), (data["main_sample"]).sum()
    )
)

negative_cashflows = data.loc[data["main_sample"], ["year", "X"]]
fig, ax = plt.subplots(figsize=(11, 6))
ax.plot(negative_cashflows["year"], negative_cashflows["X"])
ax.fill_between(
    negative_cashflows["year"],
    0,
    1,
    where=negative_cashflows["X"] < 0,
    color="red",
    alpha=0.3,
    step="mid",
    transform=ax.get_xaxis_transform(),
)
ax.axhline(y=0, color="red", linestyle="--", linewidth=1)
ax.set(ylabel="Cashflows", xlabel="Year", title="Periods with Negative Cash Flows")
fig.tight_layout()
fig.savefig(FIGURE_DIR / "negative_cash_flows.pdf", bbox_inches="tight")
plt.show()

##########
### B2 ###
##########

components = ["DIV", "DL", "BB", "ISS", "IPO"]
report_columns = components + ["X"]
sample = data.loc[data["main_sample"]].copy()

# Report partial decades at the sample boundaries (1947--1949 and 2020--2025).
sample["decade"] = (sample["year"] // 10 * 10).astype(str) + "s"
decade_averages = sample.groupby("decade", sort=True)[report_columns].mean()

sample["period"] = pd.cut(
    sample["year"],
    bins=[1946, 1981, 2025],
    labels=["1947-1981", "1982-2025"],
)
period_averages = sample.groupby("period", observed=False)[report_columns].mean()

column_labels = {
    "DIV": "DIV",
    "DL": "DL",
    "BB": "BB",
    "ISS": "ISS",
    "IPO": "IPO",
    "X": "Net payout yield",
}
percent = lambda value: f"{100 * value:.2f}%"

print("\nAverage yields by decade:")
print(
    decade_averages.rename(columns=column_labels).to_string(
        formatters={column: percent for column in column_labels.values()}
    )
)

print("\nAverage yields by subperiod:")
print(
    period_averages.rename(columns=column_labels).to_string(
        formatters={column: percent for column in column_labels.values()}
    )
)

fig, ax = plt.subplots(figsize=(11, 6))
for component in report_columns:
    ax.plot(sample["year"], 100 * sample[component], label=component, linewidth=1.5)

ax.axhline(y=0, color="black", linestyle="--", linewidth=0.8)
ax.set(
    title="Payout Components, 1947-2025",
    xlabel="Year",
    ylabel="Percent of value",
)
ax.legend(ncol=5)
ax.grid(alpha=0.25)
fig.tight_layout()
fig.savefig(FIGURE_DIR / "payout_components.pdf", bbox_inches="tight")
plt.show()

#################################
### B2(b): variance decomposition
#################################

# Because X = DIV + DL + BB - ISS - IPO, these signed covariance
# contributions add up exactly to Var(X).
signs = {"DIV": 1, "DL": 1, "BB": 1, "ISS": -1, "IPO": -1}
variance = sample["X"].var()
variance_decomposition = pd.DataFrame(
    {
        "Covariance with net payout yield": [
            sample[component].cov(sample["X"]) for component in components
        ],
        "Contribution to variance": [
            sign * sample[component].cov(sample["X"])
            for component, sign in signs.items()
        ],
    },
    index=components,
)
variance_decomposition["Share of variance"] = (
    variance_decomposition["Contribution to variance"] / variance
)

print("\nVariance decomposition of the net payout yield, 1947-2025:")
print(
    variance_decomposition.to_string(
        formatters={
            "Covariance with net payout yield": lambda value: f"{value:.8f}",
            "Contribution to variance": lambda value: f"{value:.8f}",
            "Share of variance": lambda value: f"{100 * value:.2f}%",
        }
    )
)
print(f"Net payout yield variance: {variance:.8f}")
print(
    "Sum of covariance contributions: "
    f"{variance_decomposition['Contribution to variance'].sum():.8f}"
)

sample["representative"] = sample["X"]
sample["buy_and_hold"] = sample["DIV"]
sample["gross_payouts"] = sample["DIV"] + sample["DL"] + sample["BB"]
ax = sample.plot(
    x="year",
    y=["representative", "buy_and_hold", "gross_payouts"],
    figsize=(11, 6),
    title="Payout Yields by Investor Type",
)
ax.set(xlabel="Year", ylabel="Payout yield")
ax.legend(["Representative", "Buy-and-Hold", "Gross Payout"])
ax.axhline(0, color="black", linestyle="--", linewidth=0.8)
ax.figure.tight_layout()
ax.figure.savefig(FIGURE_DIR / "investor_payout_yields.pdf", bbox_inches="tight")
plt.show()

##########
### B3 ###
##########

# B3(a): buy-and-hold investor. The payout components in the CRSP file are
# already scaled by aggregate market value, so the ratio in the A4(a) law of
# motion is DL + BB - X_minus. Here X_minus is the gross negative-payout
# yield, ISS + IPO.
data["X_plus_yield"] = data["DIV"] + data["DL"] + data["BB"]
data["X_minus_yield"] = data["ISS"] + data["IPO"]
data["s_d"] = np.nan
data.loc[data.index[0], "s_d"] = 1.0  # s^d_1925 = 1

for current_index, previous_index in zip(data.index[1:], data.index[:-1]):
    ownership_growth = (
        1
        + data.loc[current_index, "DL"]
        + data.loc[current_index, "BB"]
        - data.loc[current_index, "X_minus_yield"]
    )
    data.loc[current_index, "s_d"] = data.loc[previous_index, "s_d"] * ownership_growth

# V^d_t = s^d_t V_t and D_{t+1} = DIV_{t+1} V^d_t.
data["V_d"] = data["s_d"] * data["V"]
data["D_d"] = data["DIV"] * data["V_d"].shift(1)
data["payout_yield_d"] = data["DIV"]
data["d_minus_p"] = np.log(data["D_d"] / data["V_d"])
data["delta_d"] = np.log(data["D_d"]).diff()

b3_sample = data.loc[data["main_sample"]].copy()
mean_d_minus_p = b3_sample["d_minus_p"].mean()
rho_d = 1 / (1 + np.exp(mean_d_minus_p))

# B3(b): gross-payout investor. Because X_minus_yield is already scaled by market
# value, the A3(a) ownership law is s^g_{t+1} = s^g_t(1 - X^-_{t+1}).
data["gross_payout_yield"] = data["X_plus_yield"]
data["s_g"] = np.nan
data.loc[data.index[0], "s_g"] = 1.0  # s^g_1925 = 1

for current_index, previous_index in zip(data.index[1:], data.index[:-1]):
    ownership_growth = 1 - data.loc[current_index, "X_minus_yield"]
    data.loc[current_index, "s_g"] = data.loc[previous_index, "s_g"] * ownership_growth

# V^g_t = s^g_t V_t and X^g_{t+1} = (DIV + DL + BB)_{t+1} V^g_t.
data["V_g"] = data["s_g"] * data["V"]
data["X_g"] = data["gross_payout_yield"] * data["V_g"].shift(1)
data["x_g_minus_v_g"] = np.log(data["X_g"] / data["V_g"])
data["delta_x_g"] = np.log(data["X_g"]).diff()

b3_gross_sample = data.loc[data["main_sample"]].copy()
mean_x_g_minus_v_g = b3_gross_sample["x_g_minus_v_g"].mean()
rho_g = 1 / (1 + np.exp(mean_x_g_minus_v_g))

# B3(c): representative investor. Payouts dated t use holdings at t - 1,
# matching X_{t+1} = payout_yield_{t+1} V_t.
data["X_plus_amount"] = data["X_plus_yield"] * data["V"].shift(1)
data["X_minus_amount"] = data["X_minus_yield"] * data["V"].shift(1)
data["x_plus_minus_v"] = np.log(data["X_plus_amount"] / data["V"])
data["x_minus_minus_v"] = np.log(data["X_minus_amount"] / data["V"])

representative_sample = data.loc[data["main_sample"]].copy()
mean_x_plus_minus_v = representative_sample["x_plus_minus_v"].mean()
mean_x_minus_minus_v = representative_sample["x_minus_minus_v"].mean()
mean_positive_ratio = np.exp(mean_x_plus_minus_v)
mean_negative_ratio = np.exp(mean_x_minus_minus_v)
net_mean_payout_ratio = mean_positive_ratio - mean_negative_ratio

a = mean_positive_ratio / net_mean_payout_ratio
b = mean_negative_ratio / net_mean_payout_ratio
rho = 1 / (1 + net_mean_payout_ratio)

data["x_minus_v"] = a * data["x_plus_minus_v"] - b * data["x_minus_minus_v"]
data["log_X"] = data["x_minus_v"] + np.log(data["V"])
data["delta_x"] = data["log_X"].diff()


def ar1_slope(series):
    """Estimate y_t = constant + phi * y_{t-1} by OLS."""
    ar_data = pd.concat([series, series.shift(1)], axis=1).dropna()
    dependent = ar_data.iloc[:, 0].to_numpy()
    regressors = np.column_stack([np.ones(len(ar_data)), ar_data.iloc[:, 1].to_numpy()])
    return np.linalg.lstsq(regressors, dependent, rcond=None)[0][1]


# Report yields and log payout growth rates in percentage points.
b3_sample = data.loc[data["main_sample"]].copy()
b3_series = {
    ("Representative", "Payout yield"): b3_sample["X"],
    ("Representative", "Payout growth"): b3_sample["delta_x"],
    ("Buy-and-hold", "Payout yield"): b3_sample["payout_yield_d"],
    ("Buy-and-hold", "Payout growth"): b3_sample["delta_d"],
    ("Gross-payout", "Payout yield"): b3_sample["gross_payout_yield"],
    ("Gross-payout", "Payout growth"): b3_sample["delta_x_g"],
}

b3_summary = pd.DataFrame.from_dict(
    {
        label: {
            "Average (%)": 100 * series.mean(),
            "Standard deviation (%)": 100 * series.std(),
            "AR(1) persistence": ar1_slope(series),
        }
        for label, series in b3_series.items()
    },
    orient="index",
)
b3_summary.index = pd.MultiIndex.from_tuples(
    b3_summary.index, names=["Investor", "Variable"]
)

print("\nPayout summary by investor, 1947-2025:")
print(
    b3_summary.to_string(
        formatters={
            "Average (%)": lambda value: f"{value:.2f}",
            "Standard deviation (%)": lambda value: f"{value:.2f}",
            "AR(1) persistence": lambda value: f"{value:.3f}",
        }
    )
)


##########
### B4 ###
##########

# Log total returns: end-of-year holdings plus payouts received during the
# year, divided by beginning-of-year holdings.
data["r_d"] = np.log((data["V_d"] + data["D_d"]) / data["V_d"].shift(1))
data["r_g"] = np.log((data["V_g"] + data["X_g"]) / data["V_g"].shift(1))
data["X_amount"] = data["X"] * data["V"].shift(1)
data["r_rep"] = np.log((data["V"] + data["X_amount"]) / data["V"].shift(1))

# Growth-rate components requested in B4(b) and B4(c).
data["delta_x_plus"] = np.log(data["X_plus_amount"]).diff()
data["delta_x_minus"] = np.log(data["X_minus_amount"]).diff()
data["delta_s_g_lagged"] = np.log(data["s_g"]).diff().shift(1)

# X^g_t = s^g_{t-1} X^+_t, so these two components sum to Delta x^g_t.
assert np.allclose(
    data["delta_x_g"],
    data["delta_x_plus"] + data["delta_s_g_lagged"],
    equal_nan=True,
)


def predictive_regression(predictor, outcome):
    """Regress outcome_{t+1} on predictor_t using 1947--2024 predictors."""
    regression_data = pd.DataFrame(
        {
            "year": data["year"],
            "predictor": predictor,
            "outcome_next": outcome.shift(-1),
        }
    )
    regression_data = regression_data.loc[
        regression_data["year"].between(1947, 2024)
    ].dropna()
    regressors = sm.add_constant(regression_data["predictor"])
    result = sm.OLS(regression_data["outcome_next"], regressors).fit(cov_type="HC1")
    return {
        "Intercept": result.params["const"],
        "Robust SE (intercept)": result.bse["const"],
        "Intercept p-value": result.pvalues["const"],
        "Slope": result.params["predictor"],
        "Robust SE (slope)": result.bse["predictor"],
        "Slope p-value": result.pvalues["predictor"],
        "R-squared": result.rsquared,
    }


def significance_stars(p_value):
    """Return conventional two-sided significance stars."""
    if p_value < 0.01:
        return "***"
    if p_value < 0.05:
        return "**"
    if p_value < 0.10:
        return "*"
    return ""


investor_inputs = {
    "Buy-and-hold": {
        "yield": data["d_minus_p"],
        "return": data["r_d"],
        "growth": data["delta_d"],
        "rho": rho_d,
    },
    "Representative": {
        "yield": data["x_minus_v"],
        "return": data["r_rep"],
        "growth": data["delta_x"],
        "rho": rho,
    },
    "Gross-payout": {
        "yield": data["x_g_minus_v_g"],
        "return": data["r_g"],
        "growth": data["delta_x_g"],
        "rho": rho_g,
    },
}

b4_results = {}
for investor, inputs in investor_inputs.items():
    b4_results[(investor, "Return: r(t+1)")] = predictive_regression(
        inputs["yield"], inputs["return"]
    )
    b4_results[(investor, "Payout growth: Delta c(t+1)")] = predictive_regression(
        inputs["yield"], inputs["growth"]
    )
    b4_results[(investor, "Payout yield: y(t+1)")] = predictive_regression(
        inputs["yield"], inputs["yield"]
    )

# Additional component regressions for B4(b) and B4(c).
b4_results[("Representative", "Gross payout growth: Delta x+(t+1)")] = (
    predictive_regression(data["x_minus_v"], data["delta_x_plus"])
)
b4_results[("Representative", "Issuance growth: Delta x-(t+1)")] = (
    predictive_regression(data["x_minus_v"], data["delta_x_minus"])
)
b4_results[("Gross-payout", "Aggregate gross growth: Delta x+(t+1)")] = (
    predictive_regression(data["x_g_minus_v_g"], data["delta_x_plus"])
)
b4_results[("Gross-payout", "Ownership growth: Delta s_g(t)")] = predictive_regression(
    data["x_g_minus_v_g"], data["delta_s_g_lagged"]
)

b4_table = pd.DataFrame.from_dict(b4_results, orient="index")
b4_table.index = pd.MultiIndex.from_tuples(
    b4_table.index, names=["Investor", "Dependent variable"]
)
b4_table["b_r - b_c"] = np.nan
b4_table["1 - rho*phi"] = np.nan
b4_table["Identity gap"] = np.nan

for investor, inputs in investor_inputs.items():
    return_slope = b4_table.loc[(investor, "Return: r(t+1)"), "Slope"]
    growth_slope = b4_table.loc[(investor, "Payout growth: Delta c(t+1)"), "Slope"]
    persistence = b4_table.loc[(investor, "Payout yield: y(t+1)"), "Slope"]
    lhs = return_slope - growth_slope
    rhs = 1 - inputs["rho"] * persistence
    b4_table.loc[(investor, "Return: r(t+1)"), "b_r - b_c"] = lhs
    b4_table.loc[(investor, "Return: r(t+1)"), "1 - rho*phi"] = rhs
    b4_table.loc[(investor, "Return: r(t+1)"), "Identity gap"] = lhs - rhs

print("\nB4 one-year predictive regressions (HC1 robust standard errors):")
reported_b4_columns = [
    "Intercept",
    "Robust SE (intercept)",
    "Slope",
    "Robust SE (slope)",
    "R-squared",
    "b_r - b_c",
    "1 - rho*phi",
    "Identity gap",
]
print(
    b4_table[reported_b4_columns].to_string(
        formatters={
            column: lambda value: f"{value:.4f}" for column in reported_b4_columns
        }
    )
)


### B5 ###

# B5(a): infinite-horizon coefficients implied by the one-year VAR.
b5_long_run = {}
for investor, inputs in investor_inputs.items():
    b_r = b4_table.loc[(investor, "Return: r(t+1)"), "Slope"]
    b_c = b4_table.loc[(investor, "Payout growth: Delta c(t+1)"), "Slope"]
    phi = b4_table.loc[(investor, "Payout yield: y(t+1)"), "Slope"]
    denominator = 1 - inputs["rho"] * phi
    b_lr_r = b_r / denominator
    b_lr_c = b_c / denominator
    b5_long_run[investor] = {
        "b_LR_r": b_lr_r,
        "b_LR_c": b_lr_c,
        "Expected-return share": b_lr_r,
        "Expected-cash-flow share": -b_lr_c,
        "Share sum": b_lr_r - b_lr_c,
    }

b5_long_run_table = pd.DataFrame.from_dict(b5_long_run, orient="index")
b5_long_run_table.index.name = "Investor"

print("\nB5(a) long-run decomposition implied by the B4 VAR:")
print(
    b5_long_run_table.to_string(
        formatters={
            column: lambda value: f"{value:.4f}" for column in b5_long_run_table
        }
    )
)


def discounted_future_sum(series, rho_value, horizon=5):
    """Sum rho^(j-1) z_{t+j}, j=1,...,horizon."""
    return sum(rho_value ** (j - 1) * series.shift(-j) for j in range(1, horizon + 1))


def direct_horizon_regression(predictor, outcome):
    """Direct regression with 1947--2020 predictors and NW(4) errors."""
    regression_data = pd.DataFrame(
        {"year": data["year"], "predictor": predictor, "outcome": outcome}
    )
    regression_data = regression_data.loc[
        regression_data["year"].between(1947, 2020)
    ].dropna()
    regressors = sm.add_constant(regression_data["predictor"])
    result = sm.OLS(regression_data["outcome"], regressors).fit(
        cov_type="HAC", cov_kwds={"maxlags": 4}
    )
    return {
        "Intercept": result.params["const"],
        "NW(4) SE (intercept)": result.bse["const"],
        "Intercept p-value": result.pvalues["const"],
        "Slope": result.params["predictor"],
        "NW(4) SE (slope)": result.bse["predictor"],
        "Slope p-value": result.pvalues["predictor"],
        "R-squared": result.rsquared,
    }


# B5(b): direct five-year regressions and their VAR-implied counterparts.
b5_direct_results = {}
for investor, inputs in investor_inputs.items():
    rho_value = inputs["rho"]
    predictor = inputs["yield"]
    five_year_return = discounted_future_sum(inputs["return"], rho_value)
    five_year_growth = discounted_future_sum(inputs["growth"], rho_value)
    terminal_yield = rho_value**5 * predictor.shift(-5)

    b_r = b4_table.loc[(investor, "Return: r(t+1)"), "Slope"]
    b_c = b4_table.loc[(investor, "Payout growth: Delta c(t+1)"), "Slope"]
    phi = b4_table.loc[(investor, "Payout yield: y(t+1)"), "Slope"]
    rho_phi = rho_value * phi
    multiplier = (1 - rho_phi**5) / (1 - rho_phi)

    return_result = direct_horizon_regression(predictor, five_year_return)
    return_result["VAR-implied slope"] = b_r * multiplier
    growth_result = direct_horizon_regression(predictor, five_year_growth)
    growth_result["VAR-implied slope"] = b_c * multiplier
    yield_result = direct_horizon_regression(predictor, terminal_yield)
    yield_result["VAR-implied slope"] = rho_phi**5

    b5_direct_results[(investor, "Discounted returns")] = return_result
    b5_direct_results[(investor, "Discounted payout growth")] = growth_result
    b5_direct_results[(investor, "Discounted terminal yield")] = yield_result

b5_direct_table = pd.DataFrame.from_dict(b5_direct_results, orient="index")
b5_direct_table.index = pd.MultiIndex.from_tuples(
    b5_direct_table.index, names=["Investor", "Five-year dependent variable"]
)
b5_direct_table["Identity sum"] = np.nan
b5_direct_table["Identity gap"] = np.nan

for investor in investor_inputs:
    b5_r = b5_direct_table.loc[(investor, "Discounted returns"), "Slope"]
    b5_c = b5_direct_table.loc[(investor, "Discounted payout growth"), "Slope"]
    b5_y = b5_direct_table.loc[(investor, "Discounted terminal yield"), "Slope"]
    identity_sum = b5_r - b5_c + b5_y
    b5_direct_table.loc[(investor, "Discounted returns"), "Identity sum"] = identity_sum
    b5_direct_table.loc[(investor, "Discounted returns"), "Identity gap"] = (
        identity_sum - 1
    )

print("\nB5(b) direct five-year regressions (Newey-West SEs, 4 lags):")
reported_b5_columns = [
    "Intercept",
    "NW(4) SE (intercept)",
    "Slope",
    "NW(4) SE (slope)",
    "R-squared",
    "VAR-implied slope",
    "Identity sum",
    "Identity gap",
]
print(
    b5_direct_table[reported_b5_columns].to_string(
        formatters={
            column: lambda value: f"{value:.4f}" for column in reported_b5_columns
        }
    )
)


def save_latex_table(frame, filename, column_format, formatters=None):
    """Save a booktabs tabular fragment for inclusion in the main TeX file."""
    latex = frame.to_latex(
        escape=False,
        column_format=column_format,
        formatters=formatters,
        na_rep="",
    )
    (RESULTS_DIR / filename).write_text(latex)


def coefficient_with_stars(coefficient, p_value):
    return f"{coefficient:.4f}\\sym{{{significance_stars(p_value)}}}"


# B1
b1_latex = pd.DataFrame(
    {"Years with $X_{t+1}<0$": [f"{(sample['X'] < 0).sum()} of {len(sample)}"]},
    index=pd.Index(["1947--2025"], name="Sample"),
)
save_latex_table(b1_latex, "b1_negative_years.tex", "lr")

# B2
decade_latex = 100 * decade_averages.rename(columns=column_labels)
save_latex_table(
    decade_latex,
    "b2_decade_averages.tex",
    "lrrrrrr",
    formatters={column: lambda value: f"{value:.2f}\\%" for column in decade_latex},
)
period_latex = 100 * period_averages.rename(columns=column_labels)
save_latex_table(
    period_latex,
    "b2_period_averages.tex",
    "lrrrrrr",
    formatters={column: lambda value: f"{value:.2f}\\%" for column in period_latex},
)
variance_latex = variance_decomposition.copy()
variance_latex.loc["$\\operatorname{Var}(y)$", "Contribution to variance"] = variance
variance_latex.loc["Sum", "Contribution to variance"] = variance_decomposition[
    "Contribution to variance"
].sum()
variance_latex.loc["Sum", "Share of variance"] = 1.0
variance_latex[["Covariance with net payout yield", "Contribution to variance"]] *= 100
variance_latex = variance_latex.rename(
    columns={
        "Covariance with net payout yield": "Covariance (\\%)",
        "Contribution to variance": "Variance contribution (\\%)",
        "Share of variance": "Share (\\%)",
    }
)
save_latex_table(
    variance_latex,
    "b2_variance_decomposition.tex",
    "lrrr",
    formatters={
        "Covariance (\\%)": lambda value: f"{value:.4f}\\%",
        "Variance contribution (\\%)": lambda value: f"{value:.4f}\\%",
        "Share (\\%)": lambda value: f"{100 * value:.2f}\\%",
    },
)

# B3
latex_b3_summary = b3_summary.rename(
    columns={
        "Average (%)": "Average (\\%)",
        "Standard deviation (%)": "Standard deviation (\\%)",
    }
)
save_latex_table(
    latex_b3_summary,
    "b3_payout_summary.tex",
    "llrrr",
    formatters={column: lambda value: f"{value:.3f}" for column in latex_b3_summary},
)

# B4
b4_display = pd.DataFrame(index=b4_table.index)
b4_display["$a$"] = [
    coefficient_with_stars(row["Intercept"], row["Intercept p-value"])
    for _, row in b4_table.iterrows()
]
b4_display["SE_a"] = b4_table["Robust SE (intercept)"].map(
    lambda value: f"[{value:.4f}]"
)
b4_display["$b$"] = [
    coefficient_with_stars(row["Slope"], row["Slope p-value"])
    for _, row in b4_table.iterrows()
]
b4_display["SE_b"] = b4_table["Robust SE (slope)"].map(lambda value: f"[{value:.4f}]")
b4_display["R-squared"] = b4_table["R-squared"].map(lambda value: f"{value:.4f}")
b4_display = b4_display.rename(
    columns={
        "R-squared": "$R^2$",
    }
)
b4_label_map = {
    "Return: r(t+1)": "$r_{t+1}$",
    "Payout growth: Delta c(t+1)": "$\\Delta c_{t+1}$",
    "Payout yield: y(t+1)": "$y_{t+1}$",
    "Gross payout growth: Delta x+(t+1)": "$\\Delta x^+_{t+1}$",
    "Issuance growth: Delta x-(t+1)": "$\\Delta x^-_{t+1}$",
    "Aggregate gross growth: Delta x+(t+1)": "$\\Delta x^+_{t+1}$",
    "Ownership growth: Delta s_g(t)": "$\\Delta s^g_t$",
}
b4_display.index = pd.MultiIndex.from_tuples(
    [(investor, b4_label_map[variable]) for investor, variable in b4_display.index],
    names=["Investor", "Dependent variable"],
)
b4_tex = b4_display.to_latex(escape=False, column_format="lllrlrr", na_rep="")
b4_tex = b4_tex.replace("SE_a", "SE").replace("SE_b", "SE")
(RESULTS_DIR / "b4_regressions.tex").write_text(b4_tex)

b4_identity = pd.DataFrame(index=pd.Index(investor_inputs, name="Investor"))
for investor in investor_inputs:
    b_r = b4_table.loc[(investor, "Return: r(t+1)"), "Slope"]
    b_c = b4_table.loc[(investor, "Payout growth: Delta c(t+1)"), "Slope"]
    b4_identity.loc[investor, "$b_r$"] = b_r
    b4_identity.loc[investor, "$b_c$"] = b_c
    b4_identity.loc[investor, "$b_r-b_c$"] = b_r - b_c
    b4_identity.loc[investor, "$1-\\rho\\phi$"] = b4_table.loc[
        (investor, "Return: r(t+1)"), "1 - rho*phi"
    ]
    b4_identity.loc[investor, "Gap"] = b4_table.loc[
        (investor, "Return: r(t+1)"), "Identity gap"
    ]
save_latex_table(
    b4_identity,
    "b4_identity.tex",
    "lrrrrr",
    formatters={column: lambda value: f"{value:.4f}" for column in b4_identity},
)

# B5(a)
latex_b5_long_run = b5_long_run_table.rename(
    columns={
        "b_LR_r": "$b_r^{LR}$",
        "b_LR_c": "$b_c^{LR}$",
        "Expected-return share": "Return share",
        "Expected-cash-flow share": "Cash-flow share",
        "Share sum": "Sum",
    }
)
save_latex_table(
    latex_b5_long_run,
    "b5_long_run.tex",
    "lrrrrr",
    formatters={column: lambda value: f"{value:.4f}" for column in latex_b5_long_run},
)

# B5(b)
b5_display = pd.DataFrame(index=b5_direct_table.index)
b5_display["$a$"] = [
    coefficient_with_stars(row["Intercept"], row["Intercept p-value"])
    for _, row in b5_direct_table.iterrows()
]
b5_display["SE_a"] = b5_direct_table["NW(4) SE (intercept)"].map(
    lambda value: f"[{value:.4f}]"
)
b5_display["$b$"] = [
    coefficient_with_stars(row["Slope"], row["Slope p-value"])
    for _, row in b5_direct_table.iterrows()
]
b5_display["SE_b"] = b5_direct_table["NW(4) SE (slope)"].map(
    lambda value: f"[{value:.4f}]"
)
b5_display["R-squared"] = b5_direct_table["R-squared"].map(lambda value: f"{value:.4f}")
b5_display = b5_display.rename(
    columns={
        "R-squared": "$R^2$",
    }
)
b5_tex = b5_display.to_latex(escape=False, column_format="lllrlrr", na_rep="")
b5_tex = b5_tex.replace("SE_a", "SE").replace("SE_b", "SE")
(RESULTS_DIR / "b5_direct_regressions.tex").write_text(b5_tex)

b5_identity = pd.DataFrame(index=pd.Index(investor_inputs, name="Investor"))
b5_var_comparison = pd.DataFrame(index=pd.Index(investor_inputs, name="Investor"))
for investor in investor_inputs:
    direct_b_r = b5_direct_table.loc[(investor, "Discounted returns"), "Slope"]
    direct_b_c = b5_direct_table.loc[(investor, "Discounted payout growth"), "Slope"]
    direct_b_y = b5_direct_table.loc[(investor, "Discounted terminal yield"), "Slope"]
    identity_sum = direct_b_r - direct_b_c + direct_b_y

    b5_identity.loc[investor, "$b_r^{(5)}$"] = direct_b_r
    b5_identity.loc[investor, "$b_c^{(5)}$"] = direct_b_c
    b5_identity.loc[investor, "$b_y^{(5)}$"] = direct_b_y
    b5_identity.loc[investor, "$b_r^{(5)}-b_c^{(5)}+b_y^{(5)}$"] = identity_sum
    b5_identity.loc[investor, "Gap"] = identity_sum - 1

    var_b_r = b5_direct_table.loc[(investor, "Discounted returns"), "VAR-implied slope"]
    var_b_c = b5_direct_table.loc[
        (investor, "Discounted payout growth"), "VAR-implied slope"
    ]
    b5_var_comparison.loc[investor, "Direct $b_r^{(5)}$"] = direct_b_r
    b5_var_comparison.loc[investor, "VAR $b_r^{(5)}$"] = var_b_r
    b5_var_comparison.loc[investor, "$b_r$ gap"] = direct_b_r - var_b_r
    b5_var_comparison.loc[investor, "Direct $b_c^{(5)}$"] = direct_b_c
    b5_var_comparison.loc[investor, "VAR $b_c^{(5)}$"] = var_b_c
    b5_var_comparison.loc[investor, "$b_c$ gap"] = direct_b_c - var_b_c

save_latex_table(
    b5_identity,
    "b5_identity.tex",
    "lrrrrr",
    formatters={column: lambda value: f"{value:.4f}" for column in b5_identity},
)
save_latex_table(
    b5_var_comparison,
    "b5_var_comparison.tex",
    "lrrrrrr",
    formatters={column: lambda value: f"{value:.4f}" for column in b5_var_comparison},
)
